CREATE TABLE klasse (
  bez  TEXT PRIMARY KEY,
  raum TEXT
);
CREATE TABLE schueler (
  sch_id  INTEGER PRIMARY KEY,
  vorname TEXT NOT NULL,
  klasse  TEXT REFERENCES klasse(bez)
);
CREATE VIEW v_3ahif AS
  SELECT * FROM schueler
  WHERE klasse = '3AHIF';

SELECT type, name
FROM sqlite_master;

